net place_copies

(seed) -pulse-> [lend]
(seed) -pulse-> [recall]
(seed) -pulse-> [keep]
(lock) -pulse-> [acquire]
(lock) -pulse-> [release]
(badge) -pulse-> [lend]
(badge) -pulse-> [recall]
(badge) -pulse-> [keep]
[acquire] -pulse-> (done)
[release] -pulse-> (out)
[lend] -pulse-> (done)
[recall] -pulse-> (done)
[keep] -pulse-> (done)

(lock) annotation fusion true
(badge) annotation fusion true
decorate (lock) beside left
decorate (badge) beside

[acquire] handler "acquire@place_copies"
[release] handler "release@place_copies"
[lend] handler "lend@place_copies"
[recall] handler "recall@place_copies"
[keep] handler "keep@place_copies"

view lanes position [acquire] at {"x": 0, "y": 0}
view lanes position [release] at {"x": 300, "y": 0}
view lanes position (lock) at {"x": 150, "y": 80}
view lanes position (lock)@[acquire] relative [acquire] + {"x": -70, "y": 0}
view lanes position (lock)@[release] at {"x": 370, "y": 0}
view lanes position (done) relative (lock) + {"x": 0, "y": -40}
view lanes position (badge)@[lend] at {"x": 40, "y": 20}
view lanes position (badge)@[recall] at {"x": 80, "y": 20}
view lanes position (badge)@[keep] at {"x": 40, "y": 20}
view lanes position (out) relative (lock)@[release] + {"x": 10, "y": 0}
